insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values
('111277eb-652c-4e7b-a474-8be535e21b1a','zh','kim-dong-ryul-song-of-memory','记忆的习作','1994年“展览会”（金东律）发表、长盛不衰的经典抒情歌曲。','1993年大学歌谣祭大赏得主、二人组合“展览会”于1994年发表了《记忆的习作》。彼时乐坛以舞曲和雷鬼曲风为主流，这首抒情民谣却打动了大众的心弦。后来该曲被用作电影《建筑学概论》插曲，再度掀起广泛喜爱的热潮。','金东律与徐东旭在1993年12月以二人组合“展览会”身份参加MBC大学歌谣祭，获大赏及特别奖。次年即1994年发表由申海澈、金亨锡等参与制作的首张专辑《Exhibition》，首支曲目正是《记忆的习作》。该曲词曲编曲均由金东律一人包办，细腻的旋律自发行之初便深受喜爱。2012年电影《建筑学概论》上映后作为插曲使用，令其再度成为热点并在音源榜单上逆行走红，此后跨越世代成为韩国抒情歌曲的代表作。','谈到1990年代经典抒情歌曲时可作为代表案例提及。',null,array['기억의 습작','전람회 기억의 습작','记忆的习作'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null),
('1849c6f7-e13a-49a1-89a6-a13c87ec42d5','zh','choi-dongwon-sun-dongyeol-rivalry','崔东原-宣铜烈 铁臂对决','1987年投满15局互不相让、韩国职棒史上最经典的投手对决。','1987年5月16日，在釜山社稷球场，乐天队崔东原与海太队宣铜烈分别投出209球与232球，鏖战至延长15局才以2比2战平收场。两人此前也曾两度作为先发投手对决，各胜一场。2022年KBO联赛40周年“40大传奇球星”评选中，宣铜烈位列第一、崔东原位列第二，这场对决也因此再度被人提起。','1987年5月16日乐天-海太比赛；2022年KBO 40周年传奇球星评选使其再度受到关注。','谈及史上最强投手对决时经常被引用的KBO传奇故事。',null,array['최동원-선동열 무쇠팔 라이벌전','최동원 무쇠팔','선동열-최동원 무승부','崔东原-宣铜烈 铁臂对决'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null),
('1866f498-f749-41b1-98f4-de2d1723f95a','zh','namja-ui-jagyeok-nella-fantasia','《男人的资格》青春合唱团 Nella Fantasia','全部由高龄嘉宾组成、延续《Nella Fantasia》热潮的《男人的资格》合唱特辑。','2009年至2013年播出的KBS节目《男人的资格》曾在《Harmony》特辑中掀起《Nella Fantasia》热潮，此后又制作了成员全部由高龄人士组成的“青春合唱团”特辑。音乐总监朴柯琳（Kolleen Park）担任指挥，以极具魅力的指导方式引发热议。2011年10月末青春合唱团特辑结束后，编剧李宇汀也随之离开节目。','衍生自KBS《男人的资格》Harmony特辑，青春合唱团特辑于2011年完结。','常被提及为感动系综艺合唱形式的鼻祖。',null,array['남자의 자격 청춘합창단 넬라 판타지아','남격 합창단','청춘합창단','男人的资格 青春合唱团 Nella Fantasia'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null),
('1f6a0eef-6fe0-4508-a3ab-8abe3ced086a','zh','hiddink-still-hungry','希丁克“我依然饥饿”','2002世界杯晋级16强后，希丁克主帅留下的谦逊名言。','2002年韩日世界杯，韩国队历史性首次晋级16强后，队内一度弥漫满足情绪。主教练格斯·希丁克对此留下了这句话，传递出“不要自满、要向更大目标迈进”的信息。此后这句话被各行各业广泛引用，用以表达“不满足于现状、继续前进”之意。','2002年韩日世界杯韩国国家队主教练格斯·希丁克的采访发言。','在达成目标后强调谦逊与继续进取时引用。',null,array['히딩크 "나는 아직 배가 고프다"','아직 배고프다','히딩크 어록','希丁克 我依然饥饿'],'[{"text": "虽然达成了目标，但我依然饥饿", "situation": "KakaoTalk聊天"}, {"text": "这心态完全就是希丁克式的", "situation": "社交媒体评论"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null),
('2c7e2c44-0937-47f3-ade4-af273ce4a49e','zh','jeong-il-yeong-speech-meme','郑一荣老师说话方式梗','出演沉着叔节目的仁荷大学法语讲师，独特应对方式走红成梗的案例。','仁荷大学法语讲师郑一荣于2024年巴黎奥运会期间出演沉着叔（침착맨）频道节目。他以特有的说话方式讲述了“无票乘坐地铁被抓时”“在法国遭受不公对待时”等应对方法，引发热议。“我们是XX的顾客”“叫你们老板出来！”等表达被观众广泛套用到各种情境，成为流行梗。','2024年巴黎奥运会期间沉着叔YouTube频道播出内容。','用于表达在遭受不公对待时理直气壮据理力争的情境。','该梗曾被讹传扩散为与事实不符的内容（如兵役相关传闻），此后已有更正报道。',array['정일영 선생님 화법 밈','정일영 선생님','郑一荣老师说话方式梗'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null)
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values
('436ddcf5-5521-49ad-9a1c-32fb14ce0393','zh','lee-mal-nyun-series','李末年系列','DC Inside出身作家李末年的沙雕（无厘头）网络漫画，2009年出道作。','曾在DC Inside担任业余漫画家的李末年凭借《燃烧的巴士》等作品受到关注。2009年，他以正式网络漫画《李末年系列》出道。该作品以毫无逻辑可言的荒诞情节和沙雕风格爆红，成为无厘头网络漫画流派的代表人物。','从DC Inside业余漫画连载起步，后正式转型为网络漫画出道。','提及无厘头网络漫画鼻祖案例时使用。',null,array['이말년 씨리즈','이말년씨리즈','李末年系列'],'[{"text": "这剧情走向完全是李末年系列级别的沙雕", "situation": "KakaoTalk聊天"}, {"text": "沙雕网漫鼻祖非李末年莫属", "situation": "社交媒体评论"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null),
('47150dcf-062e-422a-b52e-71913716e2ac','zh','hongsi-mat-daejanggeum','因为有柿子味所以以为是柿子','2003年电视剧《大长今》中年幼长今循环论证式回答走红的流行语。','MBC电视剧《大长今》中，年幼的长今被郑尚宫追问肉的味道时，用“因为有柿子味，所以以为是柿子”这种循环论证式的回答作答。这一场景成为话题，一度只要打开电视，随处都能看到相关模仿桥段，风靡一时。','2003年9月29日MBC《大长今》第5集播出内容中的台词。','用于玩笑式指出对方回答逻辑不通、前后矛盾时引用。','无',array['홍시맛이 나서 홍시라 생각했는데','홍시맛이 나서 홍시라 생각한 것이온데','因为有柿子味所以以为是柿子'],'[{"text": "所以我说到底为什么啦~因为有柿子味所以以为是柿子哈哈", "situation": "KakaoTalk聊天"}, {"text": "这回答完全是循环论证式的", "situation": "社交媒体评论"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null),
('47a82b00-1c73-4829-ba79-3c6b2ac305be','zh','pc-tongsin-modem-dial-up-sound','PC通信调制解调器拨号连接音','象征1990年代PC通信及早期互联网的拨号调制解调器连接音。','1990年代通过Hitel、Nownuri等PC通信服务拨号连接时，会传出一段独特的“嘀哩哩~嗤嗤嗤~”拨号调制解调器连接音。这段声音至今仍是那个年代网络世代心中充满怀旧色彩的象征性声音。当时如果有人接起电话，连接随之中断的情况也很常见。','指1990年代初中期通过电话线连接Hitel、Chollian、Nownuri等PC通信服务时听到的“嘀~嗞嗞嗞~咝咝”拨号调制解调器信号音。这是电话线路上收发数字信号进行握手过程中产生的声音，当时用户之间常戏称其为“马桶冲水声”或“尖叫声”，成为一种通用的梗。宽带网络普及后这种声音逐渐消失，但通过采样这段声音制作的音源或YouTube怀旧视频仍不断被制作，成为唤起1980至90年代学生时代记忆的文化符号。','谈及PC通信时代的怀旧情怀时，可以模仿这段声音来回忆。',null,array['PC통신 모뎀 접속음','모뎀 접속 소리','삐- 치이이','PC通信调制解调器拨号连接音'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null),
('7cc58443-34af-46ea-b6ce-7d2dd54c8ffd','zh','looksam-look-language','Look语','源自Chzzk主播Looksam含糊发音而形成的一套新造暗语体系。','源自炉石传说职业选手出身的主播Looksam独特含混的发音，由此衍生出的一系列暗语被称为“Look语”。2025年9月初《黎明杀机》联动直播流行期间，Looksam与其他主播互动，这套暗语迅速扩散。就连Looksam本人也不知道的衍生词，也会以创造者的名字命名，称为“X体”。','源自Chzzk主播Looksam发音特点而衍生出的观众暗语。','Chzzk直播观众之间使用的暗语，不了解上下文的人很难理解。','属于粉丝圈内部用语，普通场合使用可能无法传达含义。',array['룩어','Looker','룩삼어','Look语'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null),
('7e246da6-a151-4445-bc0d-dd88b18cfc6b','zh','honeyworks-sorry-for-being-cute','因为可爱所以抱歉','配合日本组合HoneyWorks歌曲、做出飞吻与摸脸动作的舞蹈挑战。','日本创作者组合HoneyWorks的角色歌曲《因为可爱所以抱歉》于2022年11月公开音乐视频后，配合歌词做出飞吻或摸脸颊道歉动作的舞蹈挑战在TikTok上大为流行。2022年8月同人版本率先扩散并获得人气，同年12月部分K-POP偶像成员也上传了跳舞视频，使其在国内外进一步扩散。','日本组合HoneyWorks歌曲《因为可爱所以抱歉》音乐视频公开（2022年11月）。','是一段可爱风格的简短舞蹈挑战，任何人都容易跟跳。',null,array['귀여워서 미안해','可愛くてごめん','因为可爱所以抱歉'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null)
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values
('8b03db9e-2152-4fdb-a21c-77398d5c998f','zh','ongameent-starleague-launch','OnGameNet星际联赛创立','1999年至2000年韩国电子竞技职业联赛文化的起点。','1999年“99 PKO”是韩国国内电子竞技职业联赛文化的起点。从2000年“Freechal杯”开始正式采用“星际联赛（StarLeague）”这一名称的OnGameNet星际联赛，引入开放式演播室与观众席，成为韩国电子竞技观赛文化大众化的出发点。','韩国电子竞技联赛文化以1999年“99 PKO”赛事为起点萌芽，2000年Hanaro通信杯Tooniverse星际联赛首次使用“星际联赛”这一名称。借助该赛事的火爆，2000年7月24日在黄亨俊的提议下，游戏专门频道OnGameNet正式开台，最初由三四名合同工在仓库房间起步的节目，后来发展成拥有约80名员工的专业电视台。同期的2000年2月，在21世纪职业电竞协会（现韩国电子竞技协会）成立仪式上，文化观光部长官提及“电子竞技（e-sports）”一词，使该表述开始被社会广泛使用。','可作为韩国电子竞技产业起点提及。',null,array['온게임넷 스타리그 출범','스타리그','99 PKO','OnGameNet星际联赛'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null),
('984b4bc5-357d-4334-8632-0086d6697368','zh','hyundai-card-leave-if-you-worked-hard','辛勤工作的你，出发吧','2001年现代信用卡广告中鼓励旅行的经典文案。','2001年现代信用卡电视广告由郑俊浩、张真英出演，留下了“辛勤工作的你，出发吧”这句文案。此后该文案成为鼓励人们休假、旅行时常用的惯用语，并在各类旅游相关文案中被反复模仿引用。','出自现代信用卡电视广告的文案，通过对比演员郑俊浩、张真英挥汗工作与投身自然怀抱的画面呈现，背景音乐使用了Simon与Garfunkel的《The Boxer》。凭借清新时尚的影像美学引发热议并成为流行语，此后在企业裁员时期还被戏仿为“辛勤工作的你，（从公司）离开吧”等契合社会语境的变体。广告播出时间为2001年，但报道其话题性的主要新闻则见于2002年。','劝人休假或旅行时可直接引用这句话。',null,array['열심히 일한 당신, 떠나라','열일당신 떠나라','현대카드 카피','辛勤工作的你出发吧'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null),
('9b4cc86f-09ce-475c-bb83-c1ffcbab309e','zh','wonda-minecraft-but-challenge','《我的世界，但是》挑战','我的世界油管主Wonda歌曲《方块的》中加入自定义角色参与的挑战。','美国油管主camman18的“Minecraft, but”短视频形式，经韩国油管主引进后发展为《我的世界，但是》系列。在此基础上，我的世界油管主Wonda于2024年5月24日发表了由Gemmatalk、金四香献声的数字单曲《方块的》。Wonda公开了可加入自定义角色的分发文件后，众多油管主纷纷参与这场《我的世界，但是》挑战。','油管主Wonda的数字单曲《方块的》及自定义角色分发文件。','作为游戏油管主联动挑战的案例介绍。',null,array['마인크래프트인데 챌린지','네모인데','원다 네모인데','我的世界但是挑战'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null),
('9c2d304d-8053-4448-8e1f-f700c82e8e33','zh','kani-maekkeun-maekkeunhada-challenge','“光溜溜”挑战','法国出身编舞师Kani背诵韩语形容词跳舞走红的梗。','2025年10月29日，在YouTube综艺《寻找Kani》第20集中，Kani反复念着“光溜溜、光溜溜的，平平的、平平的（软软的）”等韩语形容词即兴跳舞的画面引发热议。此后“幸福披萨包”的混剪视频走红，SHINee Key、TWS、Hearts2Hearts、ZEROBASEONE等偶像纷纷模仿跳舞。恰逢韩国高考季，这段舞蹈还获得了“高考禁播曲”的绰号。','YouTube综艺《寻找Kani》第20集中背诵形容词的片段。','适合作为魔性洗脑舞蹈挑战案例介绍。',null,array['매끈매끈하다 챌린지','매끈매끈한','카니를 찾아서','수능 금지곡(2025)','光溜溜挑战'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null),
('9d430343-4454-4433-a0f8-ca4f27395272','zh','sky-castle-sseuaengnim','《SKY Castle》老湿','电视剧《SKY Castle》中演员廉晶雅将“老师”读成“老湿”而走红的流行语。','2018年播出的JTBC电视剧《SKY Castle》中，演员廉晶雅饰演的韩瑞珍苦苦哀求升学顾问金珠英（金瑞亨）时，把“老师（선생님）”发音成类似“老湿（쓰앵님）”的场景引发热议。此外，剧中“아갈머리（臭嘴）”“피라미드（金字塔）”等台词也相继成为流行语，引发各种模仿与配音秀。','JTBC电视剧《SKY Castle》韩瑞珍（廉晶雅饰）台词（2018年）。','用于戏仿苦苦哀求说服某人的情境。',null,array['SKY 캐슬 쓰앵님','아갈머리','혜나는 누가 죽였나요','SKY Castle 老湿'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null)
insert into public.meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,translated_at,reviewed_at,reviewed_by) values
('b4354c93-bfd9-4fc3-b24b-d5e1f944b3f0','zh','balletcore-fashion','芭蕾风（Balletcore）','将芭蕾舞服廓形融入日常穿搭的TikTok风尚美学。','将紧身连衣裤、缠绕裙、暖腿套、芭蕾平底鞋等芭蕾舞服元素休闲化搭配的穿搭风格，借助TikTok和Instagram上的“balletcore”标签扩散，以缎带装饰与粉彩色调的搭配为特色。在韩国国内，该风格因Red Velvet《Feel My Rhythm》、NewJeans写真等作品而被广泛认知。','2020年代初在TikTok/Instagram上，由“芭蕾（ballet）”与“基础风（normcore）”组合而成的新造词，2022年末Red Velvet回归契机使其在韩国国内搜索量骤增。','用于介绍以芭蕾平底鞋、暖腿套等单品搭配出的优雅造型。',null,array['발레코어','발레코어룩','balletcore','芭蕾风'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null),
('c4647c65-bf96-4465-b0df-c9772cb03f07','zh','park-ji-sung-two-hearts','朴智星“两颗心脏”','凭借永不知疲倦的跑动量获得的朴智星代表性绰号。','朴智星在效力曼联期间，凭借整场比赛都不知疲倦地驰骋球场的惊人跑动量，获得了“两颗心脏”的绰号。英国当地媒体还曾用“三个肺（Three-Lung Park）”来形容他的体能。实际上他的每分钟心率仅约40次，也曾被作为长期锻炼所形成的典型运动员心脏案例来介绍。','2000年代中期效力曼彻斯特联队期间的表现所奠定。','谈及朴智星出色的跑动量与体能时使用的代表性绰号。',null,array['박지성 두 개의 심장','Three-Lung Park','朴智星两颗心脏'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null),
('da72423d-7a4c-4f54-9e40-4eb18ea6d1bf','zh','produce101-pick-me-syndrome','“就是我（PICK ME）”选秀狂潮','《PRODUCE 101》第二季主题曲引发的全民选秀狂潮。','2017年4月至6月播出的Mnet《PRODUCE 101 第二季》主题曲《就是我（PICK ME）》，随练习生们的整齐群舞，掀起了席卷上半年歌谣、综艺界的全民热潮。通过该节目组成的组合Wanna One于2017年8月出道后爆红，这首歌与其编舞此后也成为各类综艺、活动中常见的模仿素材。','Mnet《PRODUCE 101 第二季》主题曲（2017年）。','作为选秀节目狂潮与群舞模仿素材被提及。',null,array['나야 나(PICK ME) 신드롬','워너원 나야나','국프 나야나','就是我 PICK ME 选秀狂潮'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null),
('dc46243d-f704-4519-ba01-bca3819b8be4','zh','be-the-reds-tshirt','“Be the Reds”T恤','成为2002世界杯全民队服的红色“Be the Reds”T恤。','红魔啦啦队制作的印有“Be the Reds!”字样的红色T恤，自2002年5月上市后仅一个月便卖出数十万件，成为全体国民争相穿着的“国民队服”。此后该设计还因版权纠纷诉讼而再度成为话题。','红魔官方啦啦队周边商品，2002年上市，设计师朴永哲绘制图案。','可作为象征2002世界杯热潮的周边商品提及。',null,array['Be the Reds 티셔츠','비더레즈','붉은악마 티셔츠','Be the Reds T恤'],'[{"text": "这次应援大家一起穿Be the Reds T恤吧", "situation": "KakaoTalk聊天"}, {"text": "那个年代真是国民队服啊", "situation": "社交媒体评论"}]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null),
('ddee812b-43f0-428f-b4ef-4133ff504ed8','zh','amazon-express-ceremony','亚马逊快车庆典','游乐园漂流设施工作人员舞蹈迟来走红成梗的案例。','爱宝乐园“亚马逊快车”自2006年起持续进行工作人员的“亚马逊欢迎庆典”惊喜舞蹈表演。2019年因网络综艺《Workman》等节目拍摄以及油管主尹啾啾的视频介绍，这段表演突然在大众间走红成为热门梗。说唱部分由尹啾啾创作，作曲编舞则由项目负责人孙荣勋负责。','爱宝乐园亚马逊快车工作人员舞蹈，2019年经网络重新走红。','可作为欢快的游乐园舞蹈素材提及。',null,array['아마존 익스프레스 세레모니','아마존 환영 세레모니','亚马逊快车庆典'],'[]'::jsonb,'machine','2026-07-15T15:30:00.191373+00:00','claude','claude-fable-5',12,now(),null,null)
